# Widgets/News & Interests components differ by Windows version (primarily Windows 11).
try { Get-Process *Widget* -ErrorAction SilentlyContinue | Stop-Process -Force -ErrorAction SilentlyContinue } catch {}
$widgetPackages = @(
  'Microsoft.WidgetsPlatformRuntime',
  'MicrosoftWindows.Client.WebExperience'
)
$removed = $false
foreach ($pkg in $widgetPackages) {
  $installed = Get-AppxPackage -Name $pkg -AllUsers -ErrorAction SilentlyContinue
  if ($installed) {
    try {
      $installed | Remove-AppxPackage -AllUsers -ErrorAction Stop
      Write-WinUtilLog -Level 'INFO' -Component 'Widgets' -Message "Removed AppX package: $pkg"
      $removed = $true
    } catch {
      Write-WinUtilLog -Level 'WARN' -Component 'Widgets' -Message "Unable to remove AppX package $pkg: $($_.Exception.Message)"
    }
  } else {
    Write-WinUtilLog -Level 'INFO' -Component 'Widgets' -Message "AppX package not present: $pkg"
  }
}
try { Invoke-WinUtilExplorerUpdate -action "restart" } catch {}
if ($removed) {
  Write-Host "Removed widgets components where present."
} else {
  Write-Host "No removable widget components were found on this system (this is expected on many Windows 10 installations)."
}

