$EdgeAppDir = "$Env:ProgramFiles (x86)\Microsoft\Edge\Application"
$SetupPath = $null
$EdgeSystemAppDir = $null

try {
    if (Test-Path -LiteralPath $EdgeAppDir -ErrorAction SilentlyContinue) {
        $SetupPath = Get-ChildItem -Path (Join-Path $EdgeAppDir '*\Installer\setup.exe') -File -ErrorAction SilentlyContinue |
            Sort-Object FullName -Descending |
            Select-Object -First 1 -ExpandProperty FullName
    }

    $systemAppsRoot = "$Env:SystemRoot\SystemApps"
    if (Test-Path -LiteralPath $systemAppsRoot -ErrorAction SilentlyContinue) {
        $EdgeSystemAppDir = Get-ChildItem -Path $systemAppsRoot -Directory -Filter 'Microsoft.MicrosoftEdge_*' -ErrorAction SilentlyContinue |
            Sort-Object FullName -Descending |
            Select-Object -First 1 -ExpandProperty FullName
    }

    if (-not $SetupPath) {
        $msg = 'Microsoft Edge installer (setup.exe) was not found. Removal is not applicable or not supported on this installation.'
        Write-WinUtilHost $msg
        Write-WinUtilLog -Level 'WARN' -Component 'RemoveEdge' -Message $msg
        return
    }
    if (-not $EdgeSystemAppDir) {
        $msg = 'Legacy Microsoft Edge system app directory was not found. Skipping removal to avoid unsupported changes on this Windows version/installation.'
        Write-WinUtilHost $msg
        Write-WinUtilLog -Level 'WARN' -Component 'RemoveEdge' -Message $msg
        return
    }

    $DummyEdgePath = Join-Path $EdgeSystemAppDir 'MicrosoftEdge.exe'
    New-Item -Path $DummyEdgePath -ItemType File -Force -ErrorAction Stop | Out-Null

    $proc = Start-Process -FilePath $SetupPath -ArgumentList '--uninstall --system-level --force-uninstall --delete-profile' -Wait -PassThru -ErrorAction Stop
    if ($proc.ExitCode -ne 0) {
        throw "Edge uninstaller exited with code $($proc.ExitCode)"
    }
    Write-WinUtilHost 'Microsoft Edge removal was attempted successfully.'
    Write-WinUtilLog -Level 'INFO' -Component 'RemoveEdge' -Message 'Microsoft Edge uninstall command completed.'
} catch {
    Write-WinUtilLog -Level 'ERROR' -Component 'RemoveEdge' -Message "Failed to remove Edge: $($_.Exception.Message)"
    Write-WinUtilHost 'Failed to uninstall Microsoft Edge. This tweak may not be supported on this Windows version/build.'
    throw
}

