$OneDrivePath = $Env:OneDrive
$OneDriveFolderExists = -not [string]::IsNullOrWhiteSpace($OneDrivePath) -and (Test-Path -LiteralPath $OneDrivePath -PathType Container -ErrorAction Stop)

$OneDriveAcl = $null
if ($OneDriveFolderExists) {
    try {
        $OneDriveAcl = Get-Acl -LiteralPath $OneDrivePath -ErrorAction Stop
    } catch {
        Write-WinUtilLog -Level 'ERROR' -Component 'RemoveOneDrive' -Message \"Failed to capture OneDrive ACL: $($_.Exception.Message)\"
        Write-WinUtilHost 'Failed to capture OneDrive folder permissions.'
    }
} else {
    Write-WinUtilHost 'OneDrive folder is already absent; skipping folder permissions and cleanup.'
    Write-WinUtilLog -Level 'INFO' -Component 'RemoveOneDrive' -Message 'OneDrive folder is already absent; skipping folder permissions and cleanup.'
}

try {
    # Protect user files while the uninstaller runs.
    if ($OneDriveFolderExists) {
        icacls \"$OneDrivePath\" /deny \"*S-1-5-32-544:(D,DC)\" /T /C
        if ($LASTEXITCODE -ne 0) { throw \"Unable to protect the OneDrive folder (icacls exit code $LASTEXITCODE).\" }
    }

    Write-WinUtilHost 'Uninstalling OneDrive...'
    $OneDriveSetupPath = (Get-ChildItem -Path \"$Env:SystemRoot\\System32\" -Filter 'OneDriveSetup.exe' -ErrorAction SilentlyContinue | Select-Object -First 1).FullName
    if (-not $OneDriveSetupPath) {
        throw 'OneDriveSetup.exe was not found in System32.'
    }
    Start-Process -FilePath $OneDriveSetupPath -ArgumentList '/uninstall' -Wait -ErrorAction Stop

    Write-WinUtilHost 'Removing leftover OneDrive Files...'
    $oneDriveProcesses = Get-Process -ErrorAction SilentlyContinue | Where-Object { $_.ProcessName -in 'OneDrive', 'FileCoAuth', 'Explorer' }
    if ($oneDriveProcesses) { $oneDriveProcesses | Stop-Process -ErrorAction Stop }

    $OneDriveLeftovers = @("$Env:LocalAppData\\Microsoft\\OneDrive", "$Env:ProgramData\\Microsoft OneDrive")
    foreach ($LeftoverPath in $OneDriveLeftovers) {
        if (Test-Path -LiteralPath $LeftoverPath -PathType Container -ErrorAction SilentlyContinue) {
            Remove-Item -LiteralPath $LeftoverPath -Recurse -Force -ErrorAction Stop
        }
    }

    # OneSyncSvc is a per-user template; Get-Service only exposes user instances.
    # Skip the operation if this Windows installation has no template.
    if (Test-Path -LiteralPath 'HKLM:\\SYSTEM\\CurrentControlSet\\Services\\OneSyncSvc') {
        Set-Service -Name OneSyncSvc -StartupType Disabled -ErrorAction Stop
    }
} catch {
    Write-WinUtilLog -Level 'ERROR' -Component 'RemoveOneDrive' -Message \"OneDrive removal failed: $($_.Exception.Message)\"
    throw
} finally {
    if ($OneDriveFolderExists -and $OneDriveAcl) {
        # Restore access even when uninstall or leftover cleanup fails.
        try {
            Set-Acl -LiteralPath $OneDrivePath -AclObject $OneDriveAcl -ErrorAction Stop
        } catch {
            Write-WinUtilLog -Level 'WARN' -Component 'RemoveOneDrive' -Message \"Failed to restore OneDrive ACL: $($_.Exception.Message)\"
        }
    }
}

if ($OneDriveFolderExists) {
    try {
        $isEmpty = (-not [System.IO.Directory]::EnumerateFileSystemEntries($OneDrivePath)) -and (Test-Path -LiteralPath $OneDrivePath -PathType Container)
    } catch {
        $isEmpty = $false
    }
    if ($isEmpty) {
        # Refuse to delete if files appeared after the emptiness check.
        try {
            [System.IO.Directory]::Delete($OneDrivePath, $false)
            [Environment]::SetEnvironmentVariable('OneDrive', $null, 'User')
        } catch {
            Write-WinUtilLog -Level 'ERROR' -Component 'RemoveOneDrive' -Message \"Failed to delete OneDrive folder: $($_.Exception.Message)\"
        }
    }
}

