InvokeScript:
$hostsPath = "$Env:SystemRoot\System32\drivers\etc\hosts"
$markerStart = '# WinUtil Adobe URL Block List Start'
$markerEnd = '# WinUtil Adobe URL Block List End'
try {
  $existing = if (Test-Path -LiteralPath $hostsPath) { Get-Content -LiteralPath $hostsPath -Raw -ErrorAction Stop } else { '' }
  if ($existing -match [regex]::Escape($markerStart)) {
    Write-WinUtilHost 'Adobe URL block list is already present in hosts file; skipping.'
    Write-WinUtilLog -Level 'INFO' -Component 'BlockAdobe' -Message 'Adobe block list already present in hosts file.'
    return
  }
  $hostsUrl = 'https://github.com/Ruddernation-Designs/Adobe-URL-Block-List/raw/refs/heads/master/hosts'
  $content = $null
  try {
    $content = Invoke-RestMethod -Uri $hostsUrl -UseBasicParsing -TimeoutSec 30 -ErrorAction Stop
  } catch {
    $msg = "Failed to download Adobe block list: $($_.Exception.Message)"
    Write-WinUtilLog -Level 'ERROR' -Component 'BlockAdobe' -Message $msg
    throw $msg
  }
  if ([string]::IsNullOrWhiteSpace([string]$content)) { throw 'Downloaded Adobe block list was empty.' }
  $trimmed = ([string]$content).Trim()
  $block = "`r`n$markerStart`r`n$trimmed`r`n$markerEnd`r`n"
  Add-Content -LiteralPath $hostsPath -Value $block -Encoding ascii -ErrorAction Stop
  ipconfig /flushdns | Out-Null
  Write-WinUtilHost 'Added Adobe URL block list to hosts file.'
  Write-WinUtilLog -Level 'INFO' -Component 'BlockAdobe' -Message 'Added Adobe URL block list to hosts file.'
} catch {
  Write-WinUtilLog -Level 'ERROR' -Component 'BlockAdobe' -Message "Failed to add Adobe block list: $($_.Exception.Message)"
  throw
}

UndoScript:
