  $pattern = '(?s)\r?\n?# WinUtil Adobe URL Block List Start.*?# WinUtil Adobe URL Block List End\r?\n?'
  $newText = [regex]::Replace($text, $pattern, '')
  if ($newText -eq $text) {
    $newText = [regex]::Replace(($text -replace "`r`n", "`n"), '(?s)#New Ver.*', '')
  }
  Set-Content -LiteralPath $hostsPath -Value $newText -Encoding ascii -ErrorAction Stop
  ipconfig /flushdns | Out-Null
  Write-WinUtilHost 'Removed Adobe URL block list from hosts file.'
  Write-WinUtilLog -Level 'INFO' -Component 'BlockAdobe' -Message 'Removed Adobe URL block list from hosts file.'
